/* crosswalk cards, a-logi. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["6·logi"]=[{"q":"A function f on the jobs with f(j) ∈ D(j) for every job j. What is f called on this page?","a":"an assignment","w":["a fair assignment","a matching","a blocking group"],"why":"It is 6b’s choosing function, picked by job."},
 {"q":"Jobs with 3, 3, 2 and 5 drivers who can take them. How many assignments?","a":"90","w":["13","16","30"],"why":"Counting-pickings: multiply the sizes, 3 · 3 · 2 · 5."},
 {"q":"An assignment that gives no driver two jobs. What is it called?","a":"fair","w":["a choosing function","a rule that picks","blocked"],"why":"f(j) = f(j′) only when j = j′: a matching of jobs with drivers."},
 {"q":"90 assignments, so 90 fair ones. What is wrong?","a":"most of the 90 give one driver two loads","w":["fair ones are counted by adding","90 is not a product","nothing: every assignment is fair"],"why":"Only 16 of the 90 are fair; the choices for s depend on g."},
 {"q":"D(g) = D(s) = D(f) = {Sarah, Randy}. What do the three jobs form?","a":"a blocking group","w":["a fair assignment","a chain","a matching"],"why":"Three jobs, two drivers between them: no fair assignment, by no-room."},
 {"q":"A set with k members cannot be matched with a part of a set with fewer. What technique is that?","a":"no-room","w":["blocking-group","one-count","lead-one-out"],"why":"Proved by induction on the smaller set, leading one out each step."},
 {"q":"A job with D(j) = ∅. What is it?","a":"a blocking group of one","w":["a fair assignment","a job any driver can take","an assignment with no output"],"why":"One job, no drivers: as 6b’s empty-member, it blocks everything."},
 {"q":"Five drivers, four jobs, so a fair assignment exists. What is wrong?","a":"some group of jobs may still be blocked","w":["five is less than four","assignments need the axiom","nothing: more drivers always suffice"],"why":"Check every group of jobs, not just the totals."},
 {"q":"g can go to Sarah or Randy, t only to Sarah. Down the board, g takes Sarah. What fixes it?","a":"a swap: g to Randy, Sarah to t","w":["nothing: no fair assignment exists","give t to Randy","drop job t"],"why":"Picking in turn can strand a job that a better order serves."},
 {"q":"40 alike cases, an order for 3, and the store takes the 3 oldest. What is that rule?","a":"least-chooses, by day of arrival","w":["left-shoes","the choice axiom","a blocking group"],"why":"The cases are socks; numbering them gives a least member to take."},
 {"q":"{D(g), D(s), D(t), D(v)} with D(g) = D(s). How many members has it?","a":"three","w":["four","two","five"],"why":"Equal sets are one member, so the picks are made by job, not by set."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["10·logi"]=[{"q":"A truck waits four hours at a dock. How many item-hours does it make there?","a":"4","w":["1","5","0"],"why":"One item-hour for each hour the truck is in the queue."},
 {"q":"Σ_{t<T} N(t) = Σ_j W_j for a window that starts and ends empty. Which technique?","a":"item-hours","w":["the queue identity","long-run","slowest-step"],"why":"One set of pairs (j, t), counted by hours and by items."},
 {"q":"L = λW. What is λ?","a":"arrivals per hour","w":["the average stay","the average number waiting","the slowest capacity"],"why":"λ = A/T, the items that arrive over the window per hour."},
 {"q":"3 trucks arrive an hour, each stays 2 hours on average. How many wait on average?","a":"6","w":["1.5","5","2"],"why":"The queue identity: L = λW = 3 · 2."},
 {"q":"On average 12 pallets sit in a cooler, and 4 arrive an hour. What is the average stay?","a":"3 hours","w":["48 hours","16 hours","8 hours"],"why":"Read backwards: W = L/λ."},
 {"q":"A window ends with the queue still full. Does L = λW hold exactly?","a":"no: the hours still to come are missing","w":["yes, whatever the window","yes, if served in order","no: it never holds"],"why":"It holds in the long run, when the gap MS/T heads to 0."},
 {"q":"Long-run needs the queue at most M items and stays at most S hours. Why?","a":"so the gap MS/T heads to 0","w":["so λ_T is a whole number","so the queue is empty","so N(t) is constant"],"why":"The squeeze far out traps λ_T W_T − L_T between 0 and MS/T."},
 {"q":"40 trips a day, 3 hours per trip, trucks working 8 hours. How many trucks at least?","a":"15","w":["40","120","5"],"why":"Truck-count: 40 × 3 ÷ 8."},
 {"q":"Trucks needed = trips per day. Is that so?","a":"no: the units do not match","w":["yes, one truck per trip","yes, for short trips","no: it is trips times trucks"],"why":"Trips per day times hours per trip, over working hours per truck."},
 {"q":"A line’s steps pass 8, 5 and 9 items an hour. What is the most it passes on?","a":"5 an hour","w":["22 an hour","8 an hour","9 an hour"],"why":"Slowest-step: every item passes the slowest step."},
 {"q":"Loads arrive at 7 an hour; the cooler passes 5. What does the line do?","a":"passes every bound","w":["settles at 2","settles at 5","empties in time"],"why":"At least (7 − 5)n wait at hour n."},
 {"q":"The cooler is the slowest step. Faster trucks are bought. What happens to the line’s output?","a":"it stays at the cooler’s pace","w":["it rises with the trucks","it doubles","it falls"],"why":"Faster trucks only arrive sooner to wait."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["14·logi"]=[{"q":"T(Q) = Kd/Q + hQ/2. What are the two parts?","a":"ordering cost a day, holding cost a day","w":["price and tax","demand and supply","order size and stock"],"why":"Orders cost K each; stock costs h a unit a day."},
 {"q":"T(Q) = Kd/Q + hQ/2 on (0, ∞). Where is it least?","a":"Q_b = √(2Kd/h)","w":["Q = Kd/h","Q = d","Q = 2Kd/h"],"why":"Equal-parts: the two parts are equal there."},
 {"q":"Sales double. What does Q_b do?","a":"it grows by √2","w":["it doubles","it halves","it stays"],"why":"Q_b goes as √d."},
 {"q":"Order 1.5 Q_b. What does the daily cost do?","a":"rises about 8%","w":["rises 50%","doubles","stays the same"],"why":"T(Q)/T(Q_b) = ½(1.5 + 1/1.5) ≈ 1.08: the curve is level near its bottom."},
 {"q":"Deliveries take L days at d a day. Reorder when the stock falls to what?","a":"dL, plus a store kept back","w":["Q_b","d","L"],"why":"What sells while a delivery is on its way."},
 {"q":"“Reorder at dL and the shelf never empties.” Right?","a":"no: only if every lead time sells exactly dL","w":["yes","yes, with Q_b","no: never reorder at dL"],"why":"Sales vary; the stock kept back covers the busier days."},
 {"q":"The stock kept back is never sold in a steady week. Does it cost nothing?","a":"no: it costs h a unit every day","w":["yes","only once","only when sold"],"why":"It sits on the shelf every day."},
 {"q":"Two stores merge. What happens to the stock they hold?","a":"1/√2 of the sum","w":["the sum","half the sum","twice the sum"],"why":"Pooled, Q_b grows by √2 for twice the sales."},
 {"q":"At Q_b, ordering cost a day and holding cost a day are…","a":"equal","w":["in the ratio 2 to 1","both 0","both least"],"why":"Equal-parts."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["16·logi"]=[{"q": "V(T) = V(0) + ∫₀ᵀ (in − out). Which technique?", "a": "tank-level", "w": ["never-dry", "pump-rate", "area-bound"], "why": "The water now is the start plus the area under in less out."},
 {"q": "Is ∫₀ᵗ (in − out) the water in the tank?", "a": "no: the change; add V(0)", "w": ["yes", "yes, at midnight", "no: it is the swing"], "why": "An area under a rate is a change."},
 {"q": "The town draws hardest at noon. Is the tank lowest then?", "a": "no: when out falls back to in", "w": ["yes", "no: at midnight", "no: when out is least"], "why": "Until out falls to in, more is going out than coming in."},
 {"q": "V(t) ≥ 0 on [0, T] exactly when V(0) is at least the greatest ∫₀ᵗ (out − in). Which technique?", "a": "never-dry", "w": ["tank-level", "pump-rate", "first-test"], "why": "Start with at least the deepest dip."},
 {"q": "The model day: the deepest dip is 110.9 m³ and the day draws 2112 m³. The least start?", "a": "110.9 m³", "w": ["2112 m³", "221.7 m³", "0 m³"], "why": "The dip, not the day's total."},
 {"q": "Crest 110.9 above the start, trough 110.9 below. What must the tank hold?", "a": "the swing, 221.7 m³", "w": ["110.9 m³", "2112 m³", "0 m³"], "why": "From crest to trough."},
 {"q": "Average outflow 88 m³/h, pump 87. What happens over many days?", "a": "it runs dry in the end", "w": ["it holds steady", "it drifts up", "it is safe with a full start"], "why": "Pump-rate: it loses 24 m³ a day."},
 {"q": "The books close at midnight every night. Can the tank still run dry?", "a": "yes: in the evening dip", "w": ["no", "only if the pump fails", "only on the last day"], "why": "A ledger that balances at the end can go below zero in the middle."},
 {"q": "in = out at t = 5.07 and at 18.93; the tank is lowest at?", "a": "18.93", "w": ["5.07", "both", "12"], "why": "5.07 is the crest: in − out changes from + to − there."},
 {"q": "Only out, lead time L, called at t. The truck finds the tank not dry when?", "a": "V(t) ≥ ∫ₜ^{t+L} out", "w": ["V(t) ≥ L · out(t)", "V(t) ≥ ∫₀ᴸ out", "V(t) ≥ out(t + L)"], "why": "What sells while the truck is on its way, with a rate that changes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["18·logi"]=[{"q": "2x + y ≤ 400. What does one limit of this form cut out?", "a": "a half-plane: one side of a line", "w": ["a corner", "a segment", "a single plan"], "why": "Sides-of-a-line: the sign of 2x + y − 400 says which side."},
 {"q": "The allowed plans hold the whole segment between any two of them. What is that set called?", "a": "convex", "w": ["bounded", "a corner", "a half-plane"], "why": "18g’s word: an intersection of half-planes is convex."},
 {"q": "Earnings 3x + 2y on a bounded region cut out by lines. Where is the largest value?", "a": "at a corner", "w": ["at the centre", "anywhere inside", "on the longest edge only"], "why": "Best-corner: on a segment a function of the first degree is never beyond both ends."},
 {"q": "A plan Q has room to spare in every limit. What does the no-middle technique say?", "a": "a small step along (3, 2) earns more", "w": ["Q is the best plan", "Q is a corner", "the region is empty"], "why": "g(Q + s(3, 2)) = g(Q) + 13s, and a small s breaks no limit."},
 {"q": "At (100, 200), stepping along both edges earns no more. What follows?", "a": "the corner is best", "w": ["the corner is the worst", "every plan ties", "a limit is broken"], "why": "Corner-holds: the region lies in the wedge of the two edges."},
 {"q": "Flour 100 kg to 101 kg moves the best plan from $700 to $704. What is $4 here?", "a": "the worth of a kilogram of flour at the margin", "w": ["the price of flour", "the earnings of a round loaf", "the cost of the oven"], "why": "Loosen one limit by one unit and read the gain."},
 {"q": "At the best plan the hands have 20 minutes spare. What is one more minute worth?", "a": "$0", "w": ["$1", "$3", "a twentieth of the earnings"], "why": "A limit with room to spare does not touch the best corner."},
 {"q": "Earnings 4x + 2y; the flour edge is 2x + y = 400. What happens?", "a": "every plan on the flour edge between two corners ties", "w": ["no best plan exists", "the best plan is in the middle of the region", "only (0, 0) is best"], "why": "The earnings line is parallel to the flour edge."},
 {"q": "The best corner is (87.5, 212.5). Is (87, 212) the best plan in whole loaves?", "a": "not necessarily: check the whole plans near it", "w": ["yes: rounding down is always best", "yes: it keeps every limit", "no: whole plans never exist"], "why": "Rounding keeps the limits, not the best."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["7·logi"]=[{"q": "A meeting from s to e. When is it going on at t?", "a": "when s ≤ t < e", "w": ["when s < t ≤ e", "when s ≤ t ≤ e", "when s < t < e"], "why": "It holds its room from its start up to, but not including, its end."},
 {"q": "One meeting ends at 11:00 and another starts at 11:00. Can they share a room?", "a": "yes", "w": ["no, they clash at 11:00", "only if they are short", "only in a bigger room"], "why": "The first is not going on at its end, 11:00."},
 {"q": "Where is the most meetings going on at once always reached?", "a": "at the start of one of them", "w": ["at the end of one of them", "at noon", "halfway through the longest one"], "why": "The busiest-start technique: take the latest start among those going on."},
 {"q": "A, B, C and D are all going on at 10:15. What can three rooms do?", "a": "not hold them, whatever the schedule", "w": ["hold them with a clever schedule", "hold them if D is short", "hold them by the first-free-room rule"], "why": "The room-count technique: four going on together need four rooms."},
 {"q": "“Suppose fewer than w rooms hold them … a collision.” What kind of proof is this?", "a": "a refutation: the statement wanted is a denial", "w": ["contradiction proper, needing not-not-out", "proof by cases on the either-way principle", "induction on the meetings"], "why": "7f's test: supposing the thing and refuting it proves its denial, with no rung 7."},
 {"q": "Meetings are taken in order of start, each given the lowest numbered room free at its start. What is this?", "a": "the first-free-room rule", "w": ["the busiest-start technique", "the room-count technique", "finite-search"], "why": "It opens a new room only when every open room is busy."},
 {"q": "The first-free-room rule opens room 4 at 14:00. What must be true at 14:00?", "a": "at least 4 meetings are going on", "w": ["exactly 3 meetings are going on", "a meeting ends at 14:00", "the rule made a mistake"], "why": "Rooms 1 to 3 are busy, and the new meeting starts then."},
 {"q": "The most going on at once is 3. How many rooms are needed?", "a": "exactly 3", "w": ["at least 4", "as many as there are meetings", "it cannot be known without trying every schedule"], "why": "Room-count gives at least 3; the first-free-room rule gives at most 3."},
 {"q": "Each of 30 meetings is given one of 3 rooms in every possible way. How many ways is that?", "a": "3³⁰", "w": ["30³", "3 · 30", "30!"], "why": "Counted-functions: a room for each meeting, 3 choices 30 times."},
 {"q": "8 meetings, 3 rooms. What decides whether they fit?", "a": "the most going on at one moment", "w": ["whether 8 is more than 3", "the length of the longest meeting", "the total hours booked"], "why": "Rooms are reused; only meetings going on together need separate rooms."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["22·logi"]=[{"q": "A depot and n stops, n ≥ 3, roads the same length both ways. How many tours?", "a": "n!/2", "w": ["n!", "2ⁿ", "n²"], "why": "Tour-count: n! orders, each loop counted once each way round."},
 {"q": "Why is n! halved in the tour-count technique?", "a": "each order driven backwards is the same loop", "w": ["the depot is fixed", "half the tours are too long", "the van comes home"], "why": "Same roads, same length; no order is its own backwards for n ≥ 3."},
 {"q": "From 20 stops, what does a machine 1000 times faster buy?", "a": "two more stops", "w": ["twenty more stops", "a thousand more stops", "nothing"], "why": "One-more-stop: 21 × 22 = 462 < 1000 < 21 × 22 × 23."},
 {"q": "(n + 1)!/2 divided by n!/2. What is it?", "a": "n + 1", "w": ["2", "n", "(n + 1)/2"], "why": "Each extra stop multiplies the tours by the new number of stops."},
 {"q": "From where you are, drive to the nearest stop not yet visited. What is this rule called on 22·logi?", "a": "the nearest-stop rule", "w": ["the tour-count technique", "the two-links floor", "brute force"], "why": "A rule of thumb: fast, no promise of the best."},
 {"q": "How many looks does the nearest-stop rule take for n stops?", "a": "n(n + 1)/2", "w": ["n!/2", "n", "2ⁿ"], "why": "n, then n − 1, … down to 1: doubled-sum."},
 {"q": "Why can the nearest-stop tour come home long?", "a": "it leaves the far stops for last", "w": ["it tries every tour", "it halves the count", "it uses one-way streets"], "why": "Near now, far later: the courier’s tour went 44 against a best of 32."},
 {"q": "Every tour ≥ ½ Σ over the places of each place’s two shortest links. What is this called?", "a": "the two-links floor technique", "w": ["the tour-count technique", "the one-more-stop technique", "the nearest-stop rule"], "why": "Every tour uses two links at every place, and each link is counted twice."},
 {"q": "A tour of 44 blocks and a floor of 28.5. What is known without trying other tours?", "a": "the tour is at most about 1.54 times the best", "w": ["the best is 28.5", "the tour is the best", "the best is 44 − 28.5"], "why": "floor ≤ best, so tour/best ≤ tour/floor."},
 {"q": "The floor is 28.5. Must some tour have length 28.5?", "a": "no; the floor is under the best and need not be met", "w": ["yes, the best tour", "yes, the nearest-stop tour", "only for 6 stops"], "why": "The courier’s best was 32."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["28·logi"]=[{"q": "On one road, the total of squared distances to the stores is lowest at …", "a": "the weighted average", "w": ["the middle store", "the farthest store", "the heaviest store"], "why": "F′(p) = 2Σ wᵢ(p − sᵢ) = 0 there."}, {"q": "On one road, the total distance to the stores is lowest at …", "a": "the store with at most half the trucks on each side", "w": ["the average", "the midpoint of the two ends", "the heaviest store"], "why": "The middle-store technique: G′ = trucks behind minus trucks ahead."}, {"q": "The farthest store moves much farther away. The middle store …", "a": "does not move", "w": ["moves halfway", "moves as far as the average", "moves the full distance"], "why": "With distance, a far store pulls no harder than a near one."}, {"q": "F(p) = Σ wᵢ|p − sᵢ|². Its uphill vector is …", "a": "2W(p − m), away from the average m", "w": ["Σ wᵢ unit vectors", "0 everywhere", "2W(m − p)"], "why": "The average-point technique, by partial slopes (28a)."}, {"q": "The uphill vector of |p − s|, for p ≠ s, is …", "a": "the unit vector from s toward p", "w": ["p − s", "2(p − s)", "the unit vector from p toward s"], "why": "Its partial slopes are (x − a)/|p − s| and (y − b)/|p − s|."}, {"q": "For total distance, each store pulls the warehouse with a force …", "a": "equal to its trucks, near or far", "w": ["growing with its distance", "shrinking with its distance", "equal for every store"], "why": "The balanced-pulls technique: ∇G = Σ wᵢeᵢ with unit vectors eᵢ."}, {"q": "Why is a point where the pulls balance the best point, and not a poor hollow?", "a": "G bends up along every line", "w": ["G is a polynomial", "the pulls are unit vectors", "G is 0 there"], "why": "The triangle inequality makes G bend up, so flat means bottom."}, {"q": "A reweighting step moves the warehouse to the average of the stores weighted by …", "a": "trucks over distance", "w": ["trucks times distance", "trucks alone", "distance alone"], "why": "The reweighting technique: a step downhill with η = 1/Σ(wᵢ/dᵢ)."}, {"q": "A reweighting step can …", "a": "never raise the total distance", "w": ["overshoot the best point", "raise the total near a store", "only be used once"], "why": "2G(p′) − G(p) ≤ H(p′) ≤ H(p) = G(p)."}, {"q": "A store is itself the best place exactly when …", "a": "its trucks are at least the size of the others’ combined pull on it", "w": ["it is the heaviest store", "it is nearest the average", "its trucks are more than half the total"], "why": "The heavy-store technique: every direction out of it climbs."}, {"q": "Near the best point the total distance is flat. So report …", "a": "the region within a stated margin of the best", "w": ["the best point to the metre", "the average point", "the nearest town"], "why": "The green box: the cloud, at the bottom."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30·logi"]=[{"q": "n ticket holders each show with chance p, independently. The count who show has chance function …", "a": "(q + ps)ⁿ", "w": ["n(q + ps)", "qⁿ + pⁿs", "q + pⁿs"], "why": "30i’s sums-multiply technique."}, {"q": "The average and spread of that count are …", "a": "np and npq", "w": ["np and np", "n and pq", "np and √(npq)"], "why": "Average-from-G (30i) and independent-spreads-add (30g)."}, {"q": "80 tickets, p = 0.92: the average count who show is …", "a": "73.6", "w": ["80", "76", "69.9"], "why": "80 × 0.92."}, {"q": "Selling ticket n + 1 lowers the average cost exactly while …", "a": "P(Sₙ ≥ c) < f/(f + b)", "w": ["P(Sₙ ≥ c) < b/(f + b)", "np < c", "P(Sₙ ≥ c) = ½"], "why": "The one-more-ticket technique."}, {"q": "With fare $150 and bump cost $800, the line is about …", "a": "0.158", "w": ["0.842", "0.5", "0.188"], "why": "150/950."}, {"q": "For the 76-seat jet at p = 0.92, the best number of tickets is …", "a": "80", "w": ["76", "83", "79"], "why": "P(S₇₉ ≥ 76) = 0.115 < 0.158 ≤ P(S₈₀ ≥ 76) = 0.223."}, {"q": "Why can a 178-seat jet overbook a bigger share than a 76-seat one?", "a": "the wobble grows like √n while the no-shows grow like n", "w": ["big planes have fewer no-shows", "bumps cost less on big planes", "the bell only fits big planes"], "why": "Width √(npq), average no-shows n q."}, {"q": "Tickets sold in pairs that show together, average unchanged. The width of the count is multiplied by …", "a": "√2", "w": ["2", "1", "½"], "why": "The groups-widen technique: spread g npq."}, {"q": "If bumps grow very costly, the one-more-ticket rule sells …", "a": "exactly as many tickets as seats", "w": ["twice the seats", "no tickets", "as many as possible"], "why": "f/(f + b) → 0."}, {"q": "An airline sells 79 tickets so that someone is bumped on about 4% of flights. This rule is …", "a": "a law with a known exception rate, as good as the estimate of p", "w": ["a guarantee that no one is bumped", "a technique proved for every flight", "wrong whenever a bump happens"], "why": "The green box: state the rule, its rate, and how well p is known."}, {"q": "Selling 76/0.92 ≈ 83 tickets bumps someone on about …", "a": "half the flights", "w": ["8% of flights", "no flights", "every flight"], "why": "The average count is then 76.4: half the time more show."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31·logi"]=[{"q": "One counter, ρ = λ/μ. Average wait before service?", "a": "ρ/(μ − λ)", "w": ["1/μ", "ρ/μ", "1/(μ − λ)"], "why": "Near-full: ρ/(1 − ρ) service times."}, {"q": "ρ from 0.9 to 0.99: the wait grows by about how much?", "a": "eleven times", "w": ["ten percent", "twice", "a hundred times"], "why": "9 to 99 service times."}, {"q": "What fact does the near-full technique hold in trust?", "a": "an arrival finds the steady chances", "w": ["service is exponential", "arrivals are rare", "ρ < 1"], "why": "True for rare-arrival streams."}, {"q": "Two or more at a shared pair of counters: service ends at what rate?", "a": "2μ", "w": ["μ", "μ/2", "λ"], "why": "First of two (30o)."}, {"q": "Shared wait over separate wait?", "a": "ρ/(1 + ρ)", "w": ["1/2", "ρ", "1/(1 + ρ)"], "why": "Shared-line."}, {"q": "Post office at noon, ρ = 0.9: two lines against one?", "a": "18 min against 8.5 min", "w": ["9 against 9", "18 against 9", "20 against 10"], "why": "The same clerks and people."}, {"q": "With separate lines, a clerk idles while someone waits with chance?", "a": "2(1 − ρ)ρ²", "w": ["1 − ρ", "ρ²", "0"], "why": "Idle-waste; about 0.16 at noon."}, {"q": "At ρ = 1, the steady line?", "a": "does not exist", "w": ["is long but steady", "has one person", "is empty"], "why": "Every steady chance would be 0."}, {"q": "One clerk twice as fast against two sharing: time in the office?", "a": "the fast clerk is less: 10 against 10.5 min", "w": ["the pair is less", "the same", "the fast clerk is 18 min"], "why": "But its wait before service is longer."}, {"q": "Average number in the office equals what?", "a": "λ times the average time there", "w": ["μ times the wait", "ρ", "1/(1 − ρ)"], "why": "Count person-hours two ways."}];
